# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import numpy as np
import pandas as pd
from typing import Dict, List


def _edge_cost(G, s, t):
    """Edge cost with None treated as prohibitive."""
    c = G[s][t].get("cost")
    return c if c is not None else 1e9


def _path_cost(G, path):
    return sum(_edge_cost(G, path[i], path[i + 1]) for i in range(len(path) - 1))


def _gen_candidates(hw, src, dst, K):
    """Generate up to K diverse low-cost simple paths src->dst."""
    cands = []
    try:
        gen = nx.shortest_simple_paths(hw, src, dst, weight="cost")
        for path in gen:
            cands.append((path, _path_cost(hw, path)))
            if len(cands) >= K:
                break
    except Exception:
        pass
    # dedupe by edge set
    seen, uniq = set(), []
    for p, c in sorted(cands, key=lambda x: x[1]):
        key = tuple(zip(p, p[1:]))
        if key not in seen:
            seen.add(key)
            uniq.append((p, c))
    return uniq[:K]


def search_algorithm(src, dsts, G, num_partitions):
    """Global broadcast routing via candidate routes + linear_sum_assignment repair.

    1. For every destination, generate K diverse low-cost simple paths
       (nx.shortest_simple_paths on cost-weighted graph, plus a second set
       under a composite cost/load weight for diversity).
    2. Assign all (dst, partition) units globally to their cheapest routes
       (no per-dst sequential bias).
    3. Repair overloaded edges: while any edge carries more flow than its
       throughput, take the units using the most overloaded edge and solve a
       rectangular assignment problem (scipy.optimize.linear_sum_assignment)
       whose columns are those units' alternative candidate routes, with
       cost = incremental route cost + big penalty for routes that still use
       overloaded edges. Swap units to alternative routes to resolve
       violations while minimizing added cost.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    # Cost-weighted view; None costs treated as prohibitive.
    hw = nx.DiGraph()
    for u, v, d in h.edges(data=True):
        c = d.get("cost")
        hw.add_edge(u, v, cost=c if c is not None else 1e9,
                    throughput=d.get("throughput") or 1e-9)

    K = 12
    routes = {}
    for dst in dsts:
        cands = _gen_candidates(hw, src, dst, K)
        if not cands:
            # composite-weight second attempt for diversity
            hw2 = nx.DiGraph()
            for u, v, d in hw.edges(data=True):
                hw2.add_edge(u, v, cost=d["cost"] * (1 + 1.0 / max(d["throughput"], 1e-6)))
            cands = _gen_candidates(hw2, src, dst, K)
        if not cands:
            cands = [([src, dst], _path_cost(hw, [src, dst]))]
        routes[dst] = cands

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    P = bc_topology.num_partitions

    # units: list of (dst, pidx); cur[unit] = chosen route index
    units = [(dst, p) for dst in dsts for p in range(P)]
    cur = {}
    for dst, _ in units:
        cur[dst] = 0  # everyone starts on their cheapest route

    def route_edges(dst, ridx):
        path = routes[dst][ridx][0]
        return [(path[i], path[i + 1]) for i in range(len(path) - 1)]

    def edge_flow():
        flow = {}
        for dst, _ in units:
            for e in route_edges(dst, cur[dst]):
                flow[e] = flow.get(e, 0) + 1
        return flow

    try:
        from scipy.optimize import linear_sum_assignment

        def cap(e):
            return hw[e[0]][e[1]].get("throughput") or 1e-9

        for _ in range(30):
            flow = edge_flow()
            overloaded = [e for e, f in flow.items() if f > cap(e)]
            if not overloaded:
                break
            # most overloaded edge
            e0 = max(overloaded, key=lambda e: flow[e] - cap(e))
            # units currently using e0
            bad = [u for u in units if e0 in route_edges(u[0], cur[u[0]])]
            if not bad:
                break
            # cost matrix: rows = bad units, cols = their candidate routes
            # (pad to rectangular with dummy columns)
            n_r = max(len(routes[u[0]]) for u in bad)
            C = np.full((len(bad), n_r), 1e12)
            for i, (dst, _) in enumerate(bad):
                for r, (path, cost) in enumerate(routes[dst]):
                    pen = 0.0
                    for k in range(len(path) - 1):
                        e = (path[k], path[k + 1])
                        if e in overloaded:
                            pen += 1e6
                    C[i, r] = cost + pen
            try:
                rows, cols = linear_sum_assignment(C)
                for i, j in zip(rows, cols):
                    if j < len(routes[bad[i][0]]) and C[i, j] < 1e11:
                        cur[bad[i][0]] = j
            except Exception:
                # fallback: move one unit to next-best route
                dst = bad[0][0]
                if len(routes[dst]) > 1:
                    cur[dst] = (cur[dst] + 1) % len(routes[dst])
    except Exception:
        pass

    for dst, p in units:
        path, _ = routes[dst][cur[dst]]
        edges = []
        for i in range(len(path) - 1):
            s, t = path[i], path[i + 1]
            edges.append([s, t, G[s][t]])
        bc_topology.set_dst_partition_paths(dst, p, edges)

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


